declare(strict_types=1);
require dirname(__DIR__).'/app/bootstrap.php';require APP_ROOT.'/app/OrderStore.php';require APP_ROOT.'/app/AlipayClient.php';$c=load_config();$p=$_POST;try{if(!$p||!ready($c))throw new RuntimeException('通知为空或配置不完整');$client=new AlipayClient($c);if(!$client->verifyNotify($p))throw new RuntimeException('RSA2 验签失败');if((string)($p['app_id']??'')!==(string)$c['app_id'])throw new RuntimeException('APPID 不匹配');$no=(string)($p['out_trade_no']??'');$o=OrderStore::get($no);if(!$o)throw new RuntimeException('本地订单不存在');$amt=number_format((float)($p['total_amount']??0),2,'.','');if(!hash_equals((string)$o['amount'],$amt))throw new RuntimeException('订单金额不匹配');$st=(string)($p['trade_status']??'');if(in_array($st,['TRADE_SUCCESS','TRADE_FINISHED'],true)){OrderStore::markPaid($no,(string)($p['trade_no']??''));log_event('ORDER_PAID_BY_NOTIFY',['order_no'=>$no,'trade_no'=>$p['trade_no']??'']);}header('Content-Type:text/plain; charset=utf-8');echo 'success';}catch(Throwable $e){log_event('NOTIFY_ERROR',['error'=>$e->getMessage(),'out_trade_no'=>$p['out_trade_no']??'']);http_response_code(400);header('Content-Type:text/plain; charset=utf-8');echo 'failure';}